<?php $money = fn($x) => number_format((float)$x, 2); ?>
<section class="card-a4"><div class="frame"><div class="sub"><?= e($s['school']['name']) ?></div><h1>كشف حساب الرسوم</h1>
  <table class="meta"><tr><td>الطالب/ة: <strong><?= e($s['student']['full_name']) ?></strong> (قيد <?= e($s['student']['student_no']) ?>)</td><td>تاريخ الطباعة: <span dir="ltr"><?= date('Y-m-d') ?></span></td></tr></table>
  <?php if (!$s['fees']): ?><p class="text-center text-muted my-4">لا توجد رسوم معيَّنة.</p><?php endif; ?>
  <?php foreach ($s['fees'] as $f): ?><h3 class="h6 mt-3"><?= e($f['structure_name']) ?> — <?= e($f['year_name']) ?> (<?= e($f['currency']) ?>)</h3>
    <table><thead><tr><th>القسط</th><th>الاستحقاق</th><th>القيمة</th><th>المسدَّد</th><th>الحالة</th></tr></thead><tbody><?php foreach ($f['installments'] as $i): $late = $i['status'] !== 'paid' && $i['due_date'] < date('Y-m-d'); ?><tr><td><?= (int)$i['seq'] ?></td><td dir="ltr"><?= e($i['due_date']) ?></td><td><?= $money($i['amount']) ?></td><td><?= $money($i['paid_amount']) ?></td><td class="<?= $late ? 'fail' : '' ?>"><?= $i['status'] === 'paid' ? 'مسدّد' : ($late ? 'متأخر' : ($i['status'] === 'partial' ? 'جزئي' : 'مستحق')) ?></td></tr><?php endforeach; ?></tbody></table>
    <?php if ($f['payments']): ?><table><thead><tr><th>السند</th><th>التاريخ</th><th>الطريقة</th><th>المبلغ</th><th>المحتسب (<?= e($f['currency']) ?>)</th></tr></thead><tbody><?php foreach ($f['payments'] as $p): ?><tr class="<?= $p['voided_at'] ? 'text-muted' : '' ?>"><td dir="ltr"><?= e($p['receipt_no']) ?><?= $p['voided_at'] ? ' (ملغى)' : '' ?></td><td dir="ltr"><?= e($p['paid_on']) ?></td><td><?= e($p['method']) ?></td><td><?= $money($p['amount']) ?> <?= e($p['currency']) ?></td><td><?= $p['voided_at'] ? '—' : $money($p['applied_amount']) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
    <table class="meta"><tr><td>المستحق: <strong><?= $money($f['payable']) ?></strong></td><td>المدفوع: <strong><?= $money($f['paid']) ?></strong></td><td>المتبقي: <strong class="<?= (float)$f['balance'] > 0 ? 'fail' : '' ?>"><?= $money($f['balance']) ?> <?= e($f['currency']) ?></strong></td></tr></table><?php endforeach; ?>
  <?php if (count($s['totals']) > 0): ?><h3 class="h6 mt-3">الإجمالي (لكل عملة)</h3><table><thead><tr><th>العملة</th><th>المستحق</th><th>المدفوع</th><th>المتبقي</th></tr></thead><tbody><?php foreach ($s['totals'] as $c => $t): ?><tr><td><?= e($c) ?></td><td><?= $money($t['payable']) ?></td><td><?= $money($t['paid']) ?></td><td class="<?= (float)$t['balance'] > 0 ? 'fail' : '' ?>"><?= $money($t['balance']) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
</div></section>
